/**
 * A footer with the brand, a tagline, groups of links and the copyright. Axes: layout (columns: brand above,
 * equal columns per group, row: the brand, the group names and the copyright in one row), signup mode (none,
 * first: a sign-up above the links), status mode (none, show: a live status pill), density. The live status
 * itself is a port contract.
 */
import { For, type JSX } from "solid-js";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { Button } from "../primitives/button/button";
import { Container } from "../primitives/container/container";
import { Form } from "../primitives/form/form";
import { Group } from "../primitives/group/group";
import { Input } from "../primitives/input/input";
import { Label } from "../primitives/label/label";
import { Link } from "../primitives/link/link";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { FooterCard } from "../components/footer-card";
import { FooterColumns } from "../components/footer-columns";
import { NavBlock } from "../components/nav-block";
import { Pill } from "../components/pill";
import { cn, tpl, uniqLabel } from "../utils";
import type { FooterSignup, FooterStatus } from "./sitemap-footer.types";
import type { MegaGroup } from "./mega-menu.types";

export type SitemapFooterProps = {
  label: string;
  brand: string;
  tagline: string;
  copyright: string;
  groups: MegaGroup[];
  signup?: FooterSignup;
  status?: FooterStatus;
  id?: string;
  layout?: "columns" | "row" | "card";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function SitemapFooter({
  label,
  brand,
  tagline,
  copyright,
  groups,
  signup,
  status,
  id = "footer",
  layout = "columns",
  density = "default",
  landmarkLabel,
}: SitemapFooterProps) {
  return (
    <>
      {((layout as string) === "card") ? (
        <FooterCard label={label} brand={brand} groups={groups} landmarkLabel={landmarkLabel} />
      ) : (
        <Block
          tag="footer"
          class="mt-12 border-t border-border"
          data-testid="site-footer"
          data-layout={layout}
          aria-label={landmarkLabel}
        >
          <Container
            class={cn(
              "mx-auto w-full max-w-6xl px-4",
              "flex flex-col gap-8",
              (((density as string) === "compact") ? "py-6" : "py-12")
            )}
            data-slot="container"
          >
            {(signup?.mode === "first") ? (
              <Stack gap="4" class="max-w-md" data-testid="signup">
                <Title as={3} size="xl" weight="bold">
                  {signup?.title}
                </Title>
                <Form method="dialog" class={cn("w-full max-w-md", (false ? "mx-auto" : ""))} data-testid="email-form">
                  <Label for={tpl("{0}-email", id)} class="sr-only">
                    {signup?.label}
                  </Label>
                  <Group gap="2" align="start" class="w-full flex-wrap">
                    <Input type="email" name="email" class="min-w-0 flex-1" id={tpl("{0}-email", id)} data-testid="field" />
                    <Button variant="default" size="default" type="submit" data-testid="submit">
                      {signup?.submit}
                    </Button>
                  </Group>
                </Form>
              </Stack>
            ) : null}
            {((layout as string) === "columns") ? (
              <Box class="flex flex-col gap-8 md:flex-row md:items-start md:gap-12" data-slot="footer-top">
                <Stack gap="2" class="md:w-64 md:shrink-0">
                  <Text size="xl" weight="bold">
                    {brand}
                  </Text>
                  <Text size="sm" class="text-muted-foreground">
                    {tagline}
                  </Text>
                </Stack>
                <Box class="min-w-0 flex-1">
                  <FooterColumns label={label} groups={groups} landmarkLabel={landmarkLabel} />
                </Box>
              </Box>
            ) : (
              <Group gap="6" align="center" justify="between" class="flex-wrap">
                <Text size="base" weight="bold">
                  {brand}
                </Text>
                <NavBlock label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", label, landmarkLabel)) : label)}>
                  <Group gap="4" class="flex-wrap">
                    <For each={groups ?? []}>{(g) => (
                      <Link href="#/" variant="default" class="text-sm" data-testid="group">
                        {g.title}
                      </Link>
                    )}</For>
                  </Group>
                </NavBlock>
              </Group>
            )}
            <Group gap="4" align="center" justify="between" class="flex-wrap border-t border-border pt-6">
              <Text size="sm" class="text-muted-foreground">
                {copyright}
              </Text>
              {(status?.mode === "show") ? (
                <Pill tone="green" icon="circle-check">
                  {status?.label}
                </Pill>
              ) : null}
            </Group>
          </Container>
        </Block>
      )}
    </>
  );
}

