export type FooterSignup = {
  /** first: the sign-up comes before the links */
  mode?: "none" | "first";
  title?: string;
  /** accessible name of the email field */
  label?: string;
  submit?: string;
};

export type FooterStatus = {
  /** show: the status pill is drawn */
  mode?: "none" | "show";
  /** text of the pill */
  label?: string;
};
